/**
 * The application frame (`design/archetypes/app-shell.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/app-shell.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  PageTransition,
  Ref,
  Render,
  SlotOutlet,
  SlotTemplate,
  agentMember,
  cell,
  classes,
  currentRailDestination,
  derived,
  elementRef,
  getters,
  goToRailDestination,
  isTemplate,
  mountEffect,
  provideOwner,
  railDestinations,
  useMember,
  watchEffect,
  type NodeTemplate,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/archetypes/app-shell.module.css'
import transitions from '@polymorph/recipes/conventions/page-transitions.module.css'
import { Button, type ButtonProps } from '../controls/Button'
import type { AppShellNavGroupProps } from './AppShellNavGroup'
import type { AppShellNavItemProps } from './AppShellNavItem'
import type { AppShellUserCardProps } from './AppShellUserCard'

export type NavItemProps = AppShellNavItemProps

export type NavGroupProps = AppShellNavGroupProps

export type UserCardProps = AppShellUserCardProps

export interface AppShellTopbar {
  leading?: NodeTemplate
  trailing?: NodeTemplate
}

/** The application frame: the inputs it takes, by the React member's prop names. */
export interface AppShellProps {
  collapsed?: boolean
  /**
   * A bounded, responsive reading surface for pages composed directly from controls.
   */
  contentLayout?: 'full' | 'page'
  defaultCollapsed?: boolean
  /**
   * Application-localized navigation names.
   */
  messages?: {
    primaryNavigation: string
    expandSidebar: string
    collapseSidebar: string
    closeNavigation: string
    openNavigation: string
    skipToContent?: string
  }
  /**
   * Where the navigation is drawn at frame widths. `'rail'` is the column at the frame's start.
   * `'top'` lays the same navigation along the frame's top row, before the topbar's slots, and
   * the rail's width collapse does not apply. Below the drawer breakpoint both are the same
   * drawer.
   */
  navigation?: 'top' | 'rail'
  pending?: boolean
  topbar?: AppShellTopbar
  /**
   * Presentation identity for page arrivals; does not key or remount children. A new key also
   * closes the small-viewport drawer.
   */
  transitionKey?: string
}

/** What AppShell hands its compound parts. */
export interface AppShellOwner {
  readonly collapsed: unknown
}

/** The application frame. */
@Component({
  selector: 'pm-app-shell',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS, provideOwner('AppShell')],
  imports: [PageTransition, Ref, Render, SlotOutlet, SlotTemplate, Button],
  // prettier-ignore
  template: `<ng-template pmSlot="banner" [pmSlotOf]="$"><ng-content select="[slot=banner]" /></ng-template>
<ng-template pmSlot="brand" [pmSlotOf]="$"><ng-content select="[slot=brand]" /></ng-template>
<ng-template pmSlot="dock" [pmSlotOf]="$"><ng-content select="[slot=dock]" /></ng-template>
<ng-template pmSlot="sidebar" [pmSlotOf]="$"><ng-content select="[slot=sidebar]" /></ng-template>
<ng-template pmSlot="sidebarFooter" [pmSlotOf]="$"><ng-content select="[slot=sidebarFooter]" /></ng-template>
<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<!-- root -->
<div
[attr.class]="e1()"
[attr.data-collapsed]="e2()"
[attr.data-navigation]="e3()"
[attr.data-drawer]="e4()"
data-member="app-shell"
><!-- skip -->
<a
[attr.class]="e5()"
href="#content"
>{{ e6() }}</a>
@if (e7()) {<!-- banner -->
<div
[attr.class]="e8()"
><ng-container [pmSlotOutlet]="'banner'" [pmSlotOf]="$" /></div>}
<!-- sidebar -->
<nav
[attr.class]="e9()"
[attr.aria-label]="e10()"
tabindex="-1"
[pmRef]="rail"
><!-- railHead -->
<div
[attr.class]="e11()"
>@if (e12()) {<!-- brand -->
<div
[attr.class]="e13()"
><ng-container [pmSlotOutlet]="'brand'" [pmSlotOf]="$" /></div>}
<!-- toggle -->
<div
[attr.class]="e14()"
[pmRef]="railToggle"
><pm-button
variant="ghost"
tone="neutral"
size="sm"
[iconOnly]="e15()"
[icon]="e16()"
[label]="e17()"
(click)="h1()"
></pm-button></div></div>
<!-- nav -->
<div
[attr.class]="e18()"
><ng-container [pmSlotOutlet]="'sidebar'" [pmSlotOf]="$" /></div>
@if (e19()) {<!-- sidebarFooter -->
<div
[attr.class]="e20()"
><ng-container [pmSlotOutlet]="'sidebarFooter'" [pmSlotOf]="$" /></div>}</nav>
<!-- topbar -->
<header
[attr.class]="e21()"
><!-- leading -->
<div
[attr.class]="e22()"
><!-- drawerToggle -->
<span
[attr.class]="e23()"
[pmRef]="drawerToggle"
><pm-button
variant="ghost"
tone="neutral"
size="sm"
[iconOnly]="e15()"
icon="menu"
[label]="e24()"
(click)="h2()"
></pm-button></span>
@if (e25()) {@if (template(e26())) {<ng-container [pmRender]="e26()" />} @else {{{ e26() }}}}</div>
<!-- trailing -->
<div
[attr.class]="e22()"
>@if (e27()) {@if (template(e28())) {<ng-container [pmRender]="e28()" />} @else {{{ e28() }}}}</div></header>
@if (e29()) {<!-- scrim -->
<button
[attr.class]="e30()"
type="button"
[attr.aria-label]="e31()"
(click)="h3()"
></button>}
<!-- content -->
<main
pmPageTransition
[transitionKey]="e32()"
[pending]="e33()"
[ribbon]="e34()"
[attr.class]="e35()"
id="content"
>@if (e36()) {<!-- page -->
<div
[attr.class]="e37()"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></div>} @else {<ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" />}</main>
@if (e38()) {<!-- dock -->
<div
[attr.class]="e39()"
><ng-container [pmSlotOutlet]="'dock'" [pmSlotOf]="$" /></div>}</div>`,
})
export class AppShell {
  readonly collapsed = input<AppShellProps['collapsed']>(undefined)
  /**
   * A bounded, responsive reading surface for pages composed directly from controls.
   */
  readonly contentLayout = input<
    Exclude<AppShellProps['contentLayout'], undefined>,
    AppShellProps['contentLayout']
  >('full', {
    transform: (value: AppShellProps['contentLayout']) => (value === undefined ? 'full' : value),
  })
  readonly defaultCollapsed = input<AppShellProps['defaultCollapsed']>(undefined)
  /**
   * Application-localized navigation names.
   */
  readonly messages = input<AppShellProps['messages']>(undefined)
  /**
   * Where the navigation is drawn at frame widths. `'rail'` is the column at the frame's start.
   * `'top'` lays the same navigation along the frame's top row, before the topbar's slots, and
   * the rail's width collapse does not apply. Below the drawer breakpoint both are the same
   * drawer.
   */
  readonly navigation = input<
    Exclude<AppShellProps['navigation'], undefined>,
    AppShellProps['navigation']
  >('rail', {
    transform: (value: AppShellProps['navigation']) => (value === undefined ? 'rail' : value),
  })
  readonly pending = input<Exclude<AppShellProps['pending'], undefined>, AppShellProps['pending']>(
    false,
    { transform: (value: AppShellProps['pending']) => (value === undefined ? false : value) },
  )
  readonly topbar = input<AppShellProps['topbar']>(undefined)
  /**
   * Presentation identity for page arrivals; does not key or remount children. A new key also
   * closes the small-viewport drawer.
   */
  readonly transitionKey = input<AppShellProps['transitionKey']>(undefined)
  readonly onCollapsedChange = output<boolean>({ alias: 'collapsedChange' })
  protected readonly $ = useMember({
    events: ['collapsedChange'],
    props: {
      collapsed: () => this.collapsed(),
      contentLayout: () => this.contentLayout(),
      defaultCollapsed: () => this.defaultCollapsed(),
      messages: () => this.messages(),
      navigation: () => this.navigation(),
      pending: () => this.pending(),
      topbar: () => this.topbar(),
      transitionKey: () => this.transitionKey(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uncontrolled = cell(() => this.$p.defaultCollapsed ?? false)
  protected readonly drawer = cell(() => false)
  protected readonly drawerToggle = elementRef<HTMLElement>()
  protected readonly rail = elementRef<HTMLElement>()
  protected readonly railToggle = elementRef<HTMLElement>()
  protected readonly held = derived(() => this.$p.collapsed ?? this.uncontrolled.value)
  protected readonly isCollapsed = derived(() => this.$p.navigation === 'rail' && this.held.value)
  protected readonly say = derived(
    () =>
      this.$p.messages ?? {
        primaryNavigation: 'Primary',
        expandSidebar: 'Expand sidebar',
        collapseSidebar: 'Collapse sidebar',
        closeNavigation: 'Close navigation',
        openNavigation: 'Open navigation',
      },
  )
  protected readonly toggle = derived(() => (): void => {
    const next = !this.held.value
    this.uncontrolled.value = next
    this.$.emit(this.onCollapsedChange, 'onCollapsedChange', next)
  })
  protected readonly template = isTemplate
  private release3: (() => void) | undefined

  constructor() {
    this.$.owner = getters<AppShellOwner>({ collapsed: () => this.isCollapsed.value })
    watchEffect(
      () => this.drawer.value,
      () => this.effect1(),
      false,
    )
    watchEffect(
      () => this.$p.transitionKey,
      () => this.effect2(),
      false,
    )
    inject(DestroyRef).onDestroy(() => this.release3?.())
    mountEffect(() => this.effect3())
  }

  protected e1() {
    return styles.shell
  }

  protected e2() {
    return this.isCollapsed.value ? '' : undefined
  }

  protected e3() {
    return this.$p.navigation === 'top' ? 'top' : undefined
  }

  protected e4() {
    return this.drawer.value ? '' : undefined
  }

  protected e5() {
    return styles.skip
  }

  protected e6() {
    return this.say.value.skipToContent ?? 'Skip to content'
  }

  protected e7() {
    return this.$.filled('banner')
  }

  protected e8() {
    if (!this.$.filled('banner')) return undefined as never
    return styles.banner
  }

  protected e9() {
    return styles.sidebar
  }

  protected e10() {
    return this.say.value.primaryNavigation
  }

  protected e11() {
    return styles.railHead
  }

  protected e12() {
    return this.$.filled('brand')
  }

  protected e13() {
    if (!this.$.filled('brand')) return undefined as never
    return styles.brand
  }

  protected e14() {
    return styles.toggle
  }

  protected e15(): ButtonProps['iconOnly'] {
    return true
  }

  protected e16(): ButtonProps['icon'] {
    return this.isCollapsed.value ? 'next' : 'previous'
  }

  protected e17(): ButtonProps['label'] {
    return this.isCollapsed.value ? this.say.value.expandSidebar : this.say.value.collapseSidebar
  }

  protected h1(): void {
    this.toggle.value()
  }

  protected e18() {
    return styles.nav
  }

  protected e19() {
    return this.$.filled('sidebarFooter')
  }

  protected e20() {
    if (!this.$.filled('sidebarFooter')) return undefined as never
    return styles.sidebarFooter
  }

  protected e21() {
    return styles.topbar
  }

  protected e22() {
    return styles.topbarSlot
  }

  protected e23() {
    return styles.drawerToggle
  }

  protected e24(): ButtonProps['label'] {
    return this.drawer.value ? this.say.value.closeNavigation : this.say.value.openNavigation
  }

  protected h2(): void {
    this.drawer.value = !this.drawer.value
  }

  protected e25() {
    return this.$p.topbar?.leading !== undefined
  }

  protected e26() {
    if (!(this.$p.topbar?.leading !== undefined)) return undefined as never
    return this.$p.topbar?.leading
  }

  protected e27() {
    return this.$p.topbar?.trailing !== undefined
  }

  protected e28() {
    if (!(this.$p.topbar?.trailing !== undefined)) return undefined as never
    return this.$p.topbar?.trailing
  }

  protected e29() {
    return this.drawer.value
  }

  protected e30() {
    if (!this.drawer.value) return undefined as never
    return styles.scrim
  }

  protected e31() {
    if (!this.drawer.value) return undefined as never
    return this.say.value.closeNavigation
  }

  protected h3(): void {
    if (!this.drawer.value) return
    this.drawer.value = false
  }

  protected e32() {
    return this.$p.transitionKey
  }

  protected e33() {
    return this.$p.pending
  }

  protected e34() {
    return transitions.indicator
  }

  protected e35() {
    return classes(
      styles.content,
      this.$p.transitionKey !== undefined ? transitions.page : undefined,
    )
  }

  protected e36() {
    return this.$p.contentLayout === 'page'
  }

  protected e37() {
    if (!(this.$p.contentLayout === 'page')) return undefined as never
    return styles.page
  }

  protected e38() {
    return this.$.filled('dock')
  }

  protected e39() {
    if (!this.$.filled('dock')) return undefined as never
    return styles.dock
  }

  private effect1(): void {
    void (this.drawer.value
      ? this.rail.value?.focus()
      : this.drawerToggle.value?.querySelector<HTMLElement>('button')?.focus())
  }

  private effect2(): void {
    this.drawer.value = false
  }

  private effect3(): void {
    this.release3?.()
    const ran = agentMember({
      member: 'AppShell',
      element: () => this.rail.value,
      state: () => ({
        collapsed: this.isCollapsed.value,
        open: this.drawer.value,
        destinations: railDestinations(this.rail.value, {
          item: styles.navItem,
          label: styles.navLabel,
        }),
        current: currentRailDestination(this.rail.value, {
          item: styles.navItem,
          label: styles.navLabel,
        }),
      }),
      actions: {
        collapse: () =>
          (() => {
            if (
              !this.railToggle.value ||
              window.getComputedStyle(this.railToggle.value).display === 'none'
            )
              throw new Error(
                'The rail has no width to change here: below the breakpoint it is a drawer, and with the navigation on top there is no rail.',
              )
            if (!this.held.value) this.toggle.value()
          })(),
        expand: () =>
          (() => {
            if (
              !this.railToggle.value ||
              window.getComputedStyle(this.railToggle.value).display === 'none'
            )
              throw new Error(
                'The rail has no width to change here: below the breakpoint it is a drawer, and with the navigation on top there is no rail.',
              )
            if (this.held.value) this.toggle.value()
          })(),
        open: () =>
          (() => {
            if (
              !this.drawerToggle.value ||
              window.getComputedStyle(this.drawerToggle.value).display === 'none'
            )
              throw new Error(
                'There is no drawer here: above the breakpoint the navigation is drawn beside the page or along its top.',
              )
            this.drawer.value = true
          })(),
        close: () =>
          (() => {
            if (
              !this.drawerToggle.value ||
              window.getComputedStyle(this.drawerToggle.value).display === 'none'
            )
              throw new Error(
                'There is no drawer here: above the breakpoint the navigation is drawn beside the page or along its top.',
              )
            this.drawer.value = false
          })(),
        go: {
          argument: 'id',
          run: (value) =>
            goToRailDestination(
              this.rail.value,
              { item: styles.navItem, label: styles.navLabel },
              value,
            ),
        },
      },
      withholds: () => [this.railToggle.value, this.drawerToggle.value],
    })
    this.release3 = () => {
      ran()
    }
  }
}
